style.css:
@-moz-document domain("example.com") {
:root{
    --mi-bg: #0f1115;
    --mi-fg: #e6eef6;
    --accent: #6fb3ff;
    --soft: 12px;
  }

  /* cuerpo */
  html, body {
    background: var(--mi-bg) !important;
    color: var(--mi-fg) !important;
    font-family: "Inter", Roboto, Arial, sans-serif !important;
    line-height: 1.45 !important;
    -webkit-font-smoothing: antialiased !important;
  }

  /* enlaces */
  a {
    color: var(--accent) !important;
    text-decoration: none !important;
  }
  a:hover { text-decoration: underline !important; }

  /* ejemplo: tarjetas y cajas */
  .card, .panel, [role="region"] {
    background: linear-gradient(180deg, rgba(255,255,255,0.02), rgba(0,0,0,0.06)) !important;
    border-radius: var(--soft) !important;
    box-shadow: 0 6px 18px rgba(0,0,0,0.45) !important;
    border: 1px solid rgba(255,255,255,0.03) !important;
  }

  /* ocultar elementos no deseados */
  .ads, .sponsored, [id^="ad-"] { display: none !important; }

  /* ajustes responsivos */
  @media (max-width: 800px) {
    body { font-size: 15px !important; }
  }
}
